result:
```sparql
SELECT ?name ?song_release_year
WHERE {
  ?singer rdf:type :singer ;
           :singer\#age ?age ;
           :singer\#song_name ?name ;
           :singer\#song_release_year ?song_release_year .
  FILTER(?age = (SELECT MIN(?age) WHERE { ?singer2 rdf:type :singer ; :singer\#age ?age . }))
}
